  Object.assign(en,{how2:"The bees wait while you draw. Releasing your first valid line starts the wave; keep drawing repairs during it.",tutorial2:"Finish the first barrier before the bees launch. They move quickly and steer around solid obstacles.",tutorial3:"Free walls can be pushed. Touch a stone, flower gate, or platform to pin a wall in place."});
  Object.assign(zhHant,{how2:"蜜蜂會等你畫完。放開第一條有效防線才會開始波次；之後仍可繼續修補。",tutorial2:"先完成第一條防線，蜜蜂才會出發。牠們速度很快，也會繞過實體障礙。",tutorial3:"未固定的防線會被推動。讓線碰到石塊、花門或平台即可固定。"});
  Object.assign(zhHans,{how2:"蜜蜂会等你画完。松开第一条有效防线才会开始波次；之后仍可继续修补。",tutorial2:"先完成第一条防线，蜜蜂才会出发。它们速度很快，也会绕过实体障碍。",tutorial3:"未固定的防线会被推动。让线碰到石块、花门或平台即可固定。"});
  Object.assign(ja,{how2:"ハチは描き終えるまで待ちます。最初の有効な線を離すとウェーブが始まり、その後も修復できます。",tutorial2:"最初の壁を完成させてからハチが出発します。ハチは速く、固い障害物を回り込みます。",tutorial3:"固定されていない壁は押されます。石・花の門・足場に線を触れさせて固定しましょう。"});
  Object.assign(ko,{how2:"벌은 그리기가 끝날 때까지 기다립니다. 첫 유효한 선에서 손을 떼면 웨이브가 시작되고 이후에도 보강할 수 있어요.",tutorial2:"첫 방어선을 완성해야 벌이 출발합니다. 빠르게 움직이며 단단한 장애물을 돌아갑니다.",tutorial3:"고정되지 않은 벽은 밀립니다. 선을 돌, 꽃문 또는 발판에 닿게 해 고정하세요."});
  Object.assign(es,{how2:"Las abejas esperan mientras dibujas. Al soltar la primera línea válida empieza la oleada; después puedes repararla.",tutorial2:"Termina la primera barrera antes de que salgan. Las abejas son rápidas y rodean obstáculos sólidos.",tutorial3:"Los muros libres pueden moverse. Toca una piedra, puerta floral o plataforma para fijarlos."});
  Object.assign(pt,{how2:"As abelhas esperam enquanto você desenha. Soltar a primeira linha válida inicia a onda; depois, continue reforçando.",tutorial2:"Termine a primeira barreira antes das abelhas partirem. Elas são rápidas e contornam obstáculos sólidos.",tutorial3:"Paredes soltas podem ser empurradas. Encoste a linha em uma pedra, portal de flores ou plataforma para fixá-la."});
  Object.assign(fr,{how2:"Les abeilles attendent pendant le tracé. Relâchez la première ligne valide pour lancer la vague, puis renforcez-la.",tutorial2:"Terminez la première barrière avant leur départ. Les abeilles sont rapides et contournent les obstacles solides.",tutorial3:"Les murs libres peuvent être poussés. Touchez une pierre, une porte fleurie ou une plateforme pour les fixer."});
  Object.assign(de,{how2:"Die Bienen warten beim Zeichnen. Beim Loslassen der ersten gültigen Linie startet die Welle; danach kannst du nachbessern.",tutorial2:"Beende die erste Barriere, bevor die Bienen starten. Sie sind schnell und umfliegen feste Hindernisse.",tutorial3:"Freie Wände können verschoben werden. Berühre Stein, Blumentor oder Plattform, um sie zu verankern."});
  Object.assign(it,{how2:"Le api aspettano mentre disegni. Rilascia la prima linea valida per avviare l'ondata, poi continua a rinforzarla.",tutorial2:"Completa la prima barriera prima che partano. Le api sono veloci e aggirano gli ostacoli solidi.",tutorial3:"I muri liberi possono essere spinti. Tocca una pietra, un portale floreale o una piattaforma per fissarli."});
  Object.assign(ru,{how2:"Пчёлы ждут, пока вы рисуете. Отпустите первую подходящую линию, чтобы начать волну; затем можно укреплять защиту.",tutorial2:"Завершите первую преграду до вылета пчёл. Они быстрые и обходят твёрдые препятствия.",tutorial3:"Свободные стены можно сдвинуть. Коснитесь линией камня, цветочных ворот или платформы, чтобы закрепить её."});
  Object.assign(hi,{how2:"मधुमक्खियाँ आपके चित्र पूरा करने तक रुकती हैं। पहली सही रेखा छोड़ते ही लहर शुरू होती है; बाद में उसे मजबूत कर सकते हैं।",tutorial2:"मधुमक्खियों के निकलने से पहले पहली दीवार पूरी करें। वे तेज़ हैं और ठोस बाधाओं के चारों ओर जाती हैं।",tutorial3:"खुली दीवारें धकेली जा सकती हैं। उन्हें रोकने के लिए रेखा को पत्थर, फूल-द्वार या मंच से जोड़ें।"});
  Object.assign(ar,{how2:"ينتظر النحل حتى تنتهي من الرسم. تبدأ الموجة عند إفلات أول خط صالح، ويمكنك تدعيمه بعد ذلك.",tutorial2:"أكمل الحاجز الأول قبل انطلاق النحل. إنه سريع ويلتف حول العوائق الصلبة.",tutorial3:"يمكن دفع الجدران الحرة. صِل الخط بحجر أو بوابة زهور أو منصة لتثبيته."});
  Object.assign(en,{pitch:"Draw nectar lines, brace them against terrain, and keep Pip safe while bees try to shove the walls aside.",rulesText:"Lines never break. Bees push any loose line they hit. Touch a line to a stone, flower gate, platform, or arena edge to lock it in place. A bee touching Pip fails the attempt.",waveStarted:"The bees are flying—watch which walls move!",barrierMoved:"A loose wall was pushed—brace it against terrain!",barrierHeld:"The anchored wall held!",tutorialTitle:"Draw, brace, and hold",tutorial2:"Loose lines can be pushed but never break.",tutorial3:"Connect your line to a stone, flower gate, platform, or edge so the bees cannot move it."});
  Object.assign(zhHant,{pitch:"畫出花蜜防線並用地形卡住，別讓蜜蜂把牆推開接近皮普。",rulesText:"防線永遠不會破。蜜蜂會推動撞到的未固定防線；讓線碰到石塊、花門、平台或場地邊緣即可卡住。蜜蜂碰到皮普就會失敗。",waveStarted:"蜜蜂出發了——注意哪一道牆正在移動！",barrierMoved:"未固定的牆被推動了——快用地形卡住！",barrierHeld:"卡住的防線撐住了！",tutorialTitle:"畫線、卡住、守住",tutorial2:"未固定的線會被推動，但永遠不會破。",tutorial3:"把線接到石塊、花門、平台或邊緣，蜜蜂就搬不走。"});
  Object.assign(zhHans,{pitch:"画出花蜜防线并用地形卡住，别让蜜蜂把墙推开接近皮普。",rulesText:"防线永远不会破。蜜蜂会推动撞到的未固定防线；让线碰到石块、花门、平台或场地边缘即可卡住。蜜蜂碰到皮普就会失败。",waveStarted:"蜜蜂出发了——注意哪一道墙正在移动！",barrierMoved:"未固定的墙被推动了——快用地形卡住！",barrierHeld:"卡住的防线撑住了！",tutorialTitle:"画线、卡住、守住",tutorial2:"未固定的线会被推动，但永远不会破。",tutorial3:"把线接到石块、花门、平台或边缘，蜜蜂就搬不走。"});
  Object.assign(ja,{pitch:"蜜の壁を描いて地形に固定し、ハチに押し退けられないようピップを守りましょう。",rulesText:"線は決して壊れません。ハチは固定されていない線を押します。石・花の門・足場・フィールド端に線を触れさせると固定できます。ハチがピップに触れると失敗です。",waveStarted:"ハチが出発しました。動く壁を見極めましょう！",barrierMoved:"壁が押されています。地形に固定しましょう！",barrierHeld:"固定した壁が持ちこたえました！",tutorialTitle:"描いて、固定して、守る",tutorial2:"固定されていない線は押されますが、壊れません。",tutorial3:"石・花の門・足場・端に線をつなぐと、ハチは動かせません。"});
  Object.assign(ko,{pitch:"꿀 벽을 그리고 지형에 고정해 벌이 밀어내지 못하게 핍을 지키세요.",rulesText:"선은 절대 부서지지 않습니다. 벌은 고정되지 않은 선을 밉니다. 돌, 꽃문, 발판 또는 경기장 가장자리에 선을 닿게 하면 고정됩니다. 벌이 핍에 닿으면 실패합니다.",waveStarted:"벌이 출발했습니다. 움직이는 벽을 살펴보세요!",barrierMoved:"느슨한 벽이 밀렸어요. 지형에 고정하세요!",barrierHeld:"고정된 벽이 버텼어요!",tutorialTitle:"그리고, 고정하고, 지키기",tutorial2:"느슨한 선은 밀리지만 절대 부서지지 않습니다.",tutorial3:"선을 돌, 꽃문, 발판 또는 가장자리에 연결하면 벌이 옮길 수 없습니다."});
  Object.assign(es,{pitch:"Dibuja muros de néctar, apóyalos en el terreno y protege a Pip mientras las abejas intentan moverlos.",rulesText:"Las líneas nunca se rompen. Las abejas empujan las líneas sueltas. Une una línea a una piedra, puerta floral, plataforma o borde para fijarla. Si una abeja toca a Pip, pierdes.",waveStarted:"¡Las abejas vuelan! Observa qué muros se mueven.",barrierMoved:"Un muro suelto se movió. ¡Apóyalo en el terreno!",barrierHeld:"¡El muro fijado resistió!",tutorialTitle:"Dibuja, fija y resiste",tutorial2:"Las líneas sueltas pueden moverse, pero nunca se rompen.",tutorial3:"Une la línea a una piedra, puerta floral, plataforma o borde para que no puedan moverla."});
  Object.assign(pt,{pitch:"Desenhe paredes de néctar, prenda-as ao terreno e proteja Pip enquanto as abelhas tentam empurrá-las.",rulesText:"As linhas nunca quebram. As abelhas empurram linhas soltas. Encoste a linha em uma pedra, portal de flores, plataforma ou borda para fixá-la. Se uma abelha tocar Pip, você perde.",waveStarted:"As abelhas partiram! Veja quais paredes se movem.",barrierMoved:"Uma parede solta foi empurrada. Prenda-a ao terreno!",barrierHeld:"A parede fixada resistiu!",tutorialTitle:"Desenhe, fixe e resista",tutorial2:"Linhas soltas podem ser empurradas, mas nunca quebram.",tutorial3:"Ligue a linha a uma pedra, portal de flores, plataforma ou borda para impedir que seja movida."});
  Object.assign(fr,{pitch:"Tracez des murs de nectar, bloquez-les contre le terrain et protégez Pip pendant que les abeilles les poussent.",rulesText:"Les lignes ne cassent jamais. Les abeilles poussent les lignes libres. Reliez une ligne à une pierre, une porte fleurie, une plateforme ou un bord pour la bloquer. Si une abeille touche Pip, la tentative échoue.",waveStarted:"Les abeilles arrivent : observez les murs qui bougent !",barrierMoved:"Un mur libre a bougé : bloquez-le contre le terrain !",barrierHeld:"Le mur bloqué a tenu !",tutorialTitle:"Tracer, bloquer, tenir",tutorial2:"Les lignes libres peuvent être poussées, mais ne cassent jamais.",tutorial3:"Reliez la ligne à une pierre, une porte fleurie, une plateforme ou un bord pour l'immobiliser."});
  Object.assign(de,{pitch:"Zeichne Nektarwände, verkeile sie am Gelände und schütze Pip, während die Bienen sie wegschieben wollen.",rulesText:"Linien brechen nie. Bienen schieben jede freie Linie. Verbinde sie mit Stein, Blumentor, Plattform oder Spielfeldrand, um sie festzusetzen. Berührt eine Biene Pip, ist der Versuch verloren.",waveStarted:"Die Bienen fliegen – beobachte, welche Wände sich bewegen!",barrierMoved:"Eine freie Wand wurde verschoben – verkeile sie am Gelände!",barrierHeld:"Die verkeilte Wand hat gehalten!",tutorialTitle:"Zeichnen, verkeilen, halten",tutorial2:"Freie Linien können verschoben werden, brechen aber nie.",tutorial3:"Verbinde die Linie mit Stein, Blumentor, Plattform oder Rand, damit die Bienen sie nicht bewegen können."});
  Object.assign(it,{pitch:"Disegna muri di nettare, incastrali nel terreno e proteggi Pip mentre le api provano a spostarli.",rulesText:"Le linee non si rompono mai. Le api spingono le linee libere. Collega una linea a una pietra, portale floreale, piattaforma o bordo per bloccarla. Se un'ape tocca Pip, perdi.",waveStarted:"Le api sono partite: guarda quali muri si muovono!",barrierMoved:"Un muro libero è stato spinto: incastralo nel terreno!",barrierHeld:"Il muro bloccato ha resistito!",tutorialTitle:"Disegna, blocca e resisti",tutorial2:"Le linee libere possono essere spinte, ma non si rompono mai.",tutorial3:"Collega la linea a una pietra, portale floreale, piattaforma o bordo per impedire alle api di spostarla."});
  Object.assign(ru,{pitch:"Рисуйте стены из нектара, упирайте их в рельеф и защищайте Пипа, пока пчёлы пытаются их сдвинуть.",rulesText:"Линии никогда не ломаются. Пчёлы сдвигают свободные линии. Соедините линию с камнем, цветочными воротами, платформой или краем поля, чтобы закрепить её. Касание Пипа означает поражение.",waveStarted:"Пчёлы летят — следите, какие стены двигаются!",barrierMoved:"Свободную стену сдвинули — уприте её в рельеф!",barrierHeld:"Закреплённая стена выдержала!",tutorialTitle:"Рисуйте, крепите, держитесь",tutorial2:"Свободные линии можно сдвинуть, но они никогда не ломаются.",tutorial3:"Соедините линию с камнем, воротами, платформой или краем, чтобы пчёлы не смогли её сдвинуть."});
  Object.assign(hi,{pitch:"मकरंद की दीवारें बनाएँ, उन्हें भूभाग से अटकाएँ और मधुमक्खियों को उन्हें हटाने से रोककर पिप को बचाएँ।",rulesText:"रेखाएँ कभी नहीं टूटतीं। मधुमक्खियाँ खुली रेखाओं को धकेलती हैं। रेखा को पत्थर, फूल-द्वार, मंच या किनारे से जोड़कर स्थिर करें। मधुमक्खी के पिप को छूते ही हार होगी।",waveStarted:"मधुमक्खियाँ आ गईं—देखें कौन-सी दीवार हिलती है!",barrierMoved:"खुली दीवार धकेली गई—उसे भूभाग से अटकाएँ!",barrierHeld:"अटकी हुई दीवार टिक गई!",tutorialTitle:"बनाएँ, अटकाएँ, बचाएँ",tutorial2:"खुली रेखाएँ धकेली जा सकती हैं, लेकिन कभी टूटती नहीं।",tutorial3:"रेखा को पत्थर, फूल-द्वार, मंच या किनारे से जोड़ें ताकि मधुमक्खियाँ उसे हिला न सकें।"});
  Object.assign(ar,{pitch:"ارسم جدران الرحيق وثبّتها بالتضاريس لحماية بيب بينما يحاول النحل دفعها بعيدًا.",rulesText:"الخطوط لا تنكسر أبدًا. يدفع النحل أي خط غير مثبت. صِل الخط بحجر أو بوابة زهور أو منصة أو حافة لتثبيته. إذا لمس النحل بيب تخسر المحاولة.",waveStarted:"انطلق النحل—راقب أي الجدران يتحرك!",barrierMoved:"دُفع جدار غير مثبت—ثبّته بالتضاريس!",barrierHeld:"صمد الجدار المثبت!",tutorialTitle:"ارسم وثبّت واصمد",tutorial2:"يمكن دفع الخطوط غير المثبتة، لكنها لا تنكسر أبدًا.",tutorial3:"صِل الخط بحجر أو بوابة زهور أو منصة أو حافة حتى لا يستطيع النحل تحريكه."});
