  Object.assign(en,{tipsText:"Make each line touch terrain at one or both ends. Gold lines are pinned; cyan lines can slide when bees hit them.",faq1a:"Yes. Add another line or connect a loose wall to terrain while nectar remains.",failText:"Use the terrain to pin the line before the bees push a path open.",chapterRules:["Learn how a loose wall slides when one bee pushes it.","Brace two approaches against nearby terrain.","Use meadow stones as strong line anchors.","Plan anchors around curved bee routes.","Spend nectar on short walls that reach solid terrain.","Combine every anchor rule to keep Pip safe."]});
  Object.assign(zhHant,{tipsText:"讓每條線的一端或兩端碰到地形。金色代表已卡住；青色防線被蜜蜂撞到時會滑動。",faq1a:"可以。花蜜足夠時，可補畫另一條線，或把未固定的牆接到地形。",failText:"利用地形把防線卡住，別讓蜜蜂推開通路。",chapterRules:["觀察一隻蜜蜂如何推動未固定的牆。","把兩側防線分別卡在附近地形。","利用草原石塊作為牢固支點。","面對彎曲蜂路，預先安排卡點。","把花蜜用在能碰到實體地形的短牆。","綜合所有卡牆規則保護皮普。"]});
  Object.assign(zhHans,{tipsText:"让每条线的一端或两端碰到地形。金色代表已卡住；青色防线被蜜蜂撞到时会滑动。",faq1a:"可以。花蜜足够时，可补画另一条线，或把未固定的墙接到地形。",failText:"利用地形把防线卡住，别让蜜蜂推开通路。",chapterRules:["观察一只蜜蜂如何推动未固定的墙。","把两侧防线分别卡在附近地形。","利用草原石块作为牢固支点。","面对弯曲蜂路，预先安排卡点。","把花蜜用在能碰到实体地形的短墙。","综合所有卡墙规则保护皮普。"]});
  Object.assign(ja,{tipsText:"線の片端か両端を地形に触れさせましょう。金色は固定済み、青色はハチに押されると動きます。",faq1a:"はい。蜜が残っていれば、線を追加したり自由な壁を地形につないだりできます。",failText:"ハチに道を開けられる前に、地形で線を固定しましょう。",chapterRules:["一匹のハチが自由な壁を動かす様子を学ぶ。","二つの進路を近くの地形で固定する。","草原の石を強い固定点に使う。","曲がる進路に合わせて固定点を選ぶ。","固い地形まで届く短い壁に蜜を使う。","すべての固定ルールでピップを守る。"]});
  Object.assign(ko,{tipsText:"선의 한쪽 또는 양쪽 끝을 지형에 닿게 하세요. 금색은 고정된 선이고, 청록색은 벌이 밀면 움직입니다.",faq1a:"네. 꿀이 남아 있으면 선을 추가하거나 느슨한 벽을 지형에 연결할 수 있어요.",failText:"벌이 길을 밀어 열기 전에 지형으로 선을 고정하세요.",chapterRules:["벌 한 마리가 느슨한 벽을 미는 모습을 배워요.","두 길의 벽을 가까운 지형에 고정해요.","초원 돌을 튼튼한 고정점으로 써요.","휘어진 벌 길에 맞춰 고정점을 계획해요.","단단한 지형까지 닿는 짧은 벽에 꿀을 써요.","모든 고정 규칙으로 핍을 지켜요."]});
  Object.assign(es,{tipsText:"Haz que uno o ambos extremos toquen el terreno. Las líneas doradas están fijas; las cian se deslizan al recibir golpes.",faq1a:"Sí. Añade otra línea o conecta un muro suelto al terreno mientras quede néctar.",failText:"Fija la línea al terreno antes de que las abejas abran un camino.",chapterRules:["Aprende cómo una abeja desliza un muro suelto.","Fija dos accesos al terreno cercano.","Usa las piedras como anclajes fuertes.","Planea anclajes para rutas curvas.","Gasta néctar en muros cortos que alcancen terreno sólido.","Combina todas las reglas para proteger a Pip."]});
  Object.assign(pt,{tipsText:"Faça uma ou ambas as pontas tocarem o terreno. Linhas douradas estão fixas; linhas ciano deslizam quando atingidas.",faq1a:"Sim. Adicione outra linha ou conecte uma parede solta ao terreno enquanto houver néctar.",failText:"Prenda a linha ao terreno antes que as abelhas abram caminho.",chapters:["Primeiro voo","Trilhas duplas","Âncoras de pedra","Rajadas de trevo","Lacunas frágeis","Maestria do mel"],pauseText:"A onda de abelhas fica congelada enquanto você faz uma pausa.",chapterRules:["Veja como uma abelha desloca uma parede solta.","Prenda duas rotas ao terreno próximo.","Use pedras como pontos de fixação fortes.","Planeje fixações para rotas curvas.","Gaste néctar em paredes curtas que alcancem terreno sólido.","Combine todas as regras para proteger Pip."]});
  Object.assign(fr,{tipsText:"Faites toucher une ou deux extrémités au terrain. Une ligne dorée est bloquée ; une ligne cyan glisse sous les chocs.",faq1a:"Oui. Ajoutez une ligne ou reliez un mur libre au terrain tant qu'il reste du nectar.",failText:"Bloquez la ligne au terrain avant que les abeilles n'ouvrent un passage.",chapterRules:["Observez une abeille pousser un mur libre.","Bloquez deux accès au terrain proche.","Utilisez les pierres comme points d'appui.","Placez des appuis sur les routes courbes.","Dépensez le nectar en murs courts reliés au terrain.","Combinez toutes les règles pour protéger Pip."]});
  Object.assign(de,{tipsText:"Lass ein oder beide Linienenden das Gelände berühren. Goldene Linien sind fest, türkise rutschen bei Treffern.",faq1a:"Ja. Zeichne eine weitere Linie oder verbinde eine freie Wand mit dem Gelände, solange Nektar bleibt.",failText:"Verkeile die Linie am Gelände, bevor die Bienen einen Weg freischieben.",chapterRules:["Sieh, wie eine Biene eine freie Wand verschiebt.","Verkeile zwei Zugänge am nahen Gelände.","Nutze Steine als starke Haltepunkte.","Plane Haltepunkte für kurvige Routen.","Nutze Nektar für kurze Wände bis zum Gelände.","Kombiniere alle Regeln, um Pip zu schützen."]});
  Object.assign(it,{tipsText:"Fai toccare al terreno una o entrambe le estremità. Le linee dorate sono bloccate; quelle ciano scivolano se colpite.",faq1a:"Sì. Aggiungi una linea o collega un muro libero al terreno finché resta nettare.",failText:"Blocca la linea al terreno prima che le api aprano un passaggio.",chapterRules:["Osserva un'ape spostare un muro libero.","Blocca due accessi al terreno vicino.","Usa le pietre come punti di blocco.","Pianifica i blocchi per percorsi curvi.","Spendi nettare in muri corti collegati al terreno.","Combina tutte le regole per proteggere Pip."]});
  Object.assign(ru,{tipsText:"Пусть один или оба конца линии касаются рельефа. Золотая линия закреплена, голубую пчёлы могут сдвинуть.",faq1a:"Да. Пока есть нектар, добавьте линию или соедините свободную стену с рельефом.",failText:"Закрепите линию рельефом, прежде чем пчёлы откроют проход.",chapterRules:["Узнайте, как пчела сдвигает свободную стену.","Закрепите два подхода на рельефе.","Используйте камни как прочные опоры.","Планируйте опоры на изогнутых маршрутах.","Тратьте нектар на короткие стены до рельефа.","Объедините все правила для защиты Пипа."]});
  Object.assign(hi,{tipsText:"रेखा का एक या दोनों सिरा भूभाग से जोड़ें। सुनहरी रेखा स्थिर है; नीली रेखा टक्कर पर खिसकती है।",faq1a:"हाँ। मकरंद रहते नई रेखा बनाएँ या खुली दीवार को भूभाग से जोड़ें।",failText:"मधुमक्खियों के रास्ता खोलने से पहले रेखा को भूभाग से अटकाएँ।",chapterRules:["देखें कि एक मधुमक्खी खुली दीवार कैसे खिसकाती है।","दो रास्तों को पास के भूभाग से अटकाएँ।","पत्थरों को मजबूत सहारा बनाएँ।","मुड़े रास्तों के लिए सहारे चुनें।","ठोस भूभाग तक पहुँचने वाली छोटी दीवारें बनाएँ।","सभी नियम मिलाकर पिप को बचाएँ।"]});
  Object.assign(ar,{tipsText:"اجعل أحد طرفي الخط أو كليهما يلمس التضاريس. الخط الذهبي مثبت، أما السماوي فيتحرك عند اصطدام النحل.",faq1a:"نعم. أضف خطًا أو صِل جدارًا حرًا بالتضاريس ما دام الرحيق متاحًا.",failText:"ثبّت الخط بالتضاريس قبل أن يفتح النحل ممرًا.",chapterRules:["تعلّم كيف تدفع نحلة جدارًا حرًا.","ثبّت مسارين بالتضاريس القريبة.","استخدم الحجارة كنقاط تثبيت قوية.","خطط للتثبيت حول المسارات المنحنية.","أنفق الرحيق على جدران قصيرة تصل للتضاريس.","اجمع كل قواعد التثبيت لحماية بيب."]});
  Object.assign(en,{rulesText:"Lines never break. Bees first search for an open route to Pip and ignore walls when a gap exists. Only when every route is sealed do they test a loose wall in many directions, move it, and stop the moment a path opens.",tutorial2:"If a gap exists, bees take it. They move a wall only when no route reaches Pip.",tutorial3:"A wall is truly pinned only when terrain blocks every tested movement direction.",pathFound:"A path opened—the bees stopped moving the wall!"});
  Object.assign(zhHant,{rulesText:"防線永遠不會破。蜜蜂會先尋找通往皮普的路；只要有洞就直接繞行，不會推牆。所有路徑都封死時，牠們才會從多個方向嘗試搬動未固定的牆，洞一出現就立刻停止搬牆。",tutorial2:"有洞時蜜蜂會直接走洞；完全沒路才會搬牆。",tutorial3:"只有地形擋住所有嘗試方向時，防線才算真正卡住。",pathFound:"通路出現了——蜜蜂停止搬牆！"});
  Object.assign(zhHans,{rulesText:"防线永远不会破。蜜蜂会先寻找通往皮普的路；只要有洞就直接绕行，不会推墙。所有路径都封死时，它们才会从多个方向尝试搬动未固定的墙，洞一出现就立刻停止搬墙。",tutorial2:"有洞时蜜蜂会直接走洞；完全没路才会搬墙。",tutorial3:"只有地形挡住所有尝试方向时，防线才算真正卡住。",pathFound:"通路出现了——蜜蜂停止搬墙！"});
  Object.assign(ja,{rulesText:"線は壊れません。ハチはまずピップへの道を探し、隙間があれば壁を押さずに通ります。すべての道が閉じた時だけ、自由な壁を多方向へ試し、道が開いた瞬間に移動をやめます。",tutorial2:"隙間があればハチはそこを通り、道がない時だけ壁を動かします。",tutorial3:"試した全方向が地形に阻まれた壁だけが、本当に固定されています。",pathFound:"道が開きました。ハチは壁の移動をやめます！"});
  Object.assign(ko,{rulesText:"선은 부서지지 않습니다. 벌은 먼저 핍에게 가는 길을 찾고 틈이 있으면 벽을 밀지 않고 통과합니다. 모든 길이 막혔을 때만 여러 방향으로 벽을 시험해 옮기며, 길이 열리는 즉시 멈춥니다.",tutorial2:"틈이 있으면 벌은 그 길을 쓰고, 길이 없을 때만 벽을 옮깁니다.",tutorial3:"시험한 모든 이동 방향이 지형에 막혀야 벽이 진짜 고정됩니다.",pathFound:"길이 열렸어요. 벌이 벽 옮기기를 멈췄습니다!"});
  Object.assign(es,{rulesText:"Las líneas no se rompen. Las abejas buscan primero una ruta hasta Pip y usan cualquier hueco sin mover muros. Solo si no hay ruta prueban mover un muro en varias direcciones y se detienen en cuanto se abre un camino.",tutorial2:"Si hay un hueco, las abejas lo usan; solo mueven muros cuando no existe ruta.",tutorial3:"Un muro solo está fijado si el terreno bloquea todas las direcciones probadas.",pathFound:"¡Se abrió un camino! Las abejas dejaron de mover el muro."});
  Object.assign(pt,{rulesText:"As linhas não quebram. As abelhas procuram primeiro uma rota até Pip e usam qualquer abertura sem mover paredes. Só sem rota elas testam mover uma parede em várias direções e param assim que um caminho surge.",tutorial2:"Se houver abertura, as abelhas passam por ela; só movem paredes quando não há rota.",tutorial3:"Uma parede só está presa quando o terreno bloqueia todas as direções testadas.",pathFound:"Um caminho abriu! As abelhas pararam de mover a parede."});
  Object.assign(fr,{rulesText:"Les lignes ne cassent pas. Les abeilles cherchent d'abord un chemin vers Pip et empruntent toute ouverture sans pousser les murs. Sans chemin, elles testent plusieurs directions pour déplacer un mur et s'arrêtent dès qu'un passage s'ouvre.",tutorial2:"S'il existe une ouverture, les abeilles l'empruntent ; elles ne déplacent un mur que sans autre chemin.",tutorial3:"Un mur n'est vraiment bloqué que si le terrain interdit toutes les directions testées.",pathFound:"Un passage s'est ouvert : les abeilles arrêtent de déplacer le mur !"});
  Object.assign(de,{rulesText:"Linien brechen nicht. Bienen suchen zuerst einen offenen Weg zu Pip und nutzen jede Lücke, ohne Wände zu bewegen. Nur ohne Weg testen sie viele Schieberichtungen und stoppen sofort, sobald ein Pfad offen ist.",tutorial2:"Bei einer Lücke nehmen die Bienen den Weg; nur ohne Route bewegen sie eine Wand.",tutorial3:"Eine Wand ist nur fest, wenn das Gelände alle getesteten Richtungen blockiert.",pathFound:"Ein Weg ist offen – die Bienen bewegen die Wand nicht weiter!"});
  Object.assign(it,{rulesText:"Le linee non si rompono. Le api cercano prima un percorso verso Pip e usano ogni varco senza spostare muri. Solo senza percorso provano più direzioni per muovere un muro e si fermano appena si apre un passaggio.",tutorial2:"Se c'è un varco, le api lo usano; muovono un muro solo quando non esiste un percorso.",tutorial3:"Un muro è davvero bloccato solo se il terreno impedisce ogni direzione provata.",pathFound:"Si è aperto un passaggio: le api hanno smesso di muovere il muro!"});
  Object.assign(ru,{rulesText:"Линии не ломаются. Пчёлы сначала ищут путь к Пипу и используют любую щель, не двигая стены. Только если пути нет, они пробуют сдвигать стену в разных направлениях и останавливаются сразу после открытия прохода.",tutorial2:"Если есть щель, пчёлы летят через неё; стену они двигают только при полном отсутствии пути.",tutorial3:"Стена закреплена только тогда, когда рельеф блокирует все проверенные направления.",pathFound:"Проход открыт — пчёлы перестали двигать стену!"});
  Object.assign(hi,{rulesText:"रेखाएँ नहीं टूटतीं। मधुमक्खियाँ पहले पिप तक खुला रास्ता खोजती हैं और छेद मिलने पर दीवार नहीं हिलातीं। रास्ता पूरी तरह बंद होने पर ही वे कई दिशाओं में दीवार खिसकाती हैं और रास्ता खुलते ही रुक जाती हैं।",tutorial2:"छेद हो तो मधुमक्खियाँ उसी से जाती हैं; रास्ता न होने पर ही दीवार हिलाती हैं।",tutorial3:"दीवार तभी सच में अटकी है जब भूभाग हर जाँची दिशा रोकता है।",pathFound:"रास्ता खुल गया—मधुमक्खियों ने दीवार हिलाना रोक दिया!"});
  Object.assign(ar,{rulesText:"الخطوط لا تنكسر. يبحث النحل أولًا عن طريق مفتوح إلى بيب ويستخدم أي فجوة من دون تحريك الجدران. فقط عند انعدام الطريق يجرّب تحريك جدار في اتجاهات متعددة ويتوقف فور ظهور ممر.",tutorial2:"إذا وُجدت فجوة يسلكها النحل؛ ولا يحرك الجدار إلا عند انعدام الطريق.",tutorial3:"لا يكون الجدار مثبتًا حقًا إلا إذا منعت التضاريس كل اتجاهات الحركة المختبرة.",pathFound:"انفتح ممر—توقف النحل عن تحريك الجدار!"});
  Object.assign(en,{tipsText:"A straight line between two stones is still loose. Wrap around a round obstacle or hook around a platform corner; locked walls glow gold.",tutorial3:"A straight bridge stays movable. Wrap a stone or hook around a platform corner to create a real lock.",failText:"The wall stayed loose. Wrap terrain or hook a platform corner before the bees reach Pip."});
  Object.assign(zhHant,{tipsText:"兩顆石頭中間畫直線仍是鬆動牆。要繞住圓形障礙，或鉤住平台轉角；真正固定後會呈現金色。",tutorial3:"直線橋接仍會被搬走；繞住石頭或鉤住平台轉角，才算真正卡牢。",failText:"牆沒有真正卡牢；下次要繞住地形或鉤住平台轉角。"});
  Object.assign(zhHans,{tipsText:"两颗石头中间画直线仍是松动墙。要绕住圆形障碍，或钩住平台转角；真正固定后会呈现金色。",tutorial3:"直线桥接仍会被搬走；绕住石头或钩住平台转角，才算真正卡牢。",failText:"墙没有真正卡牢；下次要绕住地形或钩住平台转角。"});
  Object.assign(ja,{tipsText:"2つの石を直線で結ぶだけでは壁は動きます。丸い障害物を囲むか、足場の角にフックを掛けると金色に固定されます。",tutorial3:"直線の橋は動かされます。石を囲むか足場の角に掛けて、本当に固定しましょう。",failText:"壁は固定されていません。地形を囲むか、足場の角に掛けましょう。"});
  Object.assign(ko,{tipsText:"돌 두 개 사이를 직선으로 잇기만 하면 벽은 움직입니다. 둥근 장애물을 감싸거나 발판 모서리에 걸면 금색으로 고정됩니다.",tutorial3:"직선 다리는 옮겨집니다. 돌을 감싸거나 발판 모서리에 걸어야 진짜 고정됩니다.",failText:"벽이 제대로 고정되지 않았어요. 지형을 감싸거나 발판 모서리에 걸어 보세요."});
  Object.assign(es,{tipsText:"Una línea recta entre dos piedras sigue suelta. Rodea un obstáculo redondo o engancha una esquina de plataforma; el muro fijado brilla dorado.",tutorial3:"Un puente recto se puede mover. Rodea una piedra o engancha una esquina para fijarlo de verdad.",failText:"El muro quedó suelto. Rodea el terreno o engancha una esquina antes de que lleguen a Pip."});
  Object.assign(pt,{tipsText:"Uma linha reta entre duas pedras continua solta. Contorne um obstáculo redondo ou enganche um canto da plataforma; a parede fixa fica dourada.",tutorial3:"Uma ponte reta pode ser movida. Contorne uma pedra ou enganche um canto para fixá-la de verdade.",failText:"A parede ficou solta. Contorne o terreno ou enganche um canto antes que cheguem a Pip."});
  Object.assign(fr,{tipsText:"Une ligne droite entre deux pierres reste libre. Entourez un obstacle rond ou accrochez un angle de plateforme ; un mur fixé devient doré.",tutorial3:"Un pont droit reste mobile. Entourez une pierre ou accrochez un angle pour le bloquer réellement.",failText:"Le mur est resté libre. Entourez le terrain ou accrochez un angle avant que les abeilles atteignent Pip."});
  Object.assign(de,{tipsText:"Eine gerade Linie zwischen zwei Steinen bleibt beweglich. Umschlinge ein rundes Hindernis oder hake sie um eine Plattform-Ecke; feste Wände leuchten golden.",tutorial3:"Eine gerade Brücke bleibt beweglich. Umschlinge einen Stein oder hake eine Ecke ein, um sie wirklich zu fixieren.",failText:"Die Wand blieb beweglich. Umschlinge Gelände oder hake eine Plattform-Ecke ein."});
  Object.assign(it,{tipsText:"Una linea retta tra due pietre resta mobile. Avvolgi un ostacolo rotondo o aggancia un angolo della piattaforma; il muro fissato diventa dorato.",tutorial3:"Un ponte diritto resta mobile. Avvolgi una pietra o aggancia un angolo per bloccarlo davvero.",failText:"Il muro è rimasto mobile. Avvolgi il terreno o aggancia un angolo prima che le api raggiungano Pip."});
  Object.assign(ru,{tipsText:"Прямая линия между двумя камнями остаётся подвижной. Обведите круглый объект или зацепите угол платформы; закреплённая стена станет золотой.",tutorial3:"Прямой мост можно сдвинуть. Обведите камень или зацепите угол платформы, чтобы закрепить стену.",failText:"Стена осталась подвижной. Обведите объект или зацепите угол платформы."});
  Object.assign(hi,{tipsText:"दो पत्थरों के बीच सीधी रेखा ढीली रहती है। गोल बाधा को घेरें या मंच के कोने पर हुक बनाएँ; स्थिर दीवार सुनहरी दिखेगी।",tutorial3:"सीधा पुल हिल सकता है। पत्थर को घेरें या मंच के कोने पर हुक लगाकर सच में स्थिर करें।",failText:"दीवार ढीली रही। भूभाग को घेरें या मंच के कोने पर हुक लगाएँ।"});
  Object.assign(ar,{tipsText:"يبقى الخط المستقيم بين حجرين قابلًا للحركة. لفّ الخط حول عائق دائري أو علّقه بزاوية منصة؛ يضيء الجدار المثبت بالذهبي.",tutorial3:"يمكن تحريك الجسر المستقيم. لفّ حجرًا أو علّق زاوية منصة لتثبيت الجدار فعلًا.",failText:"بقي الجدار متحركًا. لفّ التضاريس أو علّق زاوية منصة قبل وصول النحل إلى بيب."});
  // Final physical-gameplay copy. These assignments intentionally supersede the
  // retired route-search wording above so every public locale describes the
  // same collision, pushing, rotation, and deliberate terrain-lock rules.
  Object.assign(en,{rulesText:"Lines never break. Bees keep chasing Pip, and every collision pushes and twists a loose wall. Only a deliberate wrap around an obstacle or hook around a platform corner locks a wall; if a bee touches Pip, the attempt fails.",tutorial2:"Bees always chase Pip. Loose cyan walls slide and rotate when struck, while terrain-locked gold walls bounce them away.",tipsText:"A straight line between two stones is still loose. Wrap around a round obstacle or hook around a platform corner; locked walls glow gold.",tutorial3:"A straight bridge stays movable. Wrap a stone or hook around a platform corner to create a real lock.",failText:"The wall stayed loose. Wrap terrain or hook a platform corner before the bees reach Pip."});
  Object.assign(zhHant,{rulesText:"線條永遠不會斷裂。蜜蜂會持續追擊皮普，每次撞擊都會推動並旋轉未固定的牆。只有刻意繞住障礙或勾住平台轉角才能鎖定牆；蜜蜂碰到皮普就會失敗。",tutorial2:"蜜蜂會一直追擊皮普。青色鬆牆受撞擊會滑動與旋轉，卡住地形的金色牆則會把蜜蜂彈開。",tipsText:"兩顆石頭之間的直線仍是鬆牆。繞住圓形障礙或勾住平台轉角；鎖定的牆會發出金光。",tutorial3:"筆直架橋仍可被移動。繞住石頭或勾住平台轉角，才能真正鎖定。",failText:"牆仍未固定。請在蜜蜂碰到皮普前繞住地形或勾住平台轉角。"});
  Object.assign(zhHans,{rulesText:"线条永远不会断裂。蜜蜂会持续追击皮普，每次撞击都会推动并旋转未固定的墙。只有刻意绕住障碍或钩住平台转角才能锁定墙；蜜蜂碰到皮普就会失败。",tutorial2:"蜜蜂会一直追击皮普。青色松墙受撞击会滑动和旋转，卡住地形的金色墙会把蜜蜂弹开。",tipsText:"两颗石头之间的直线仍是松墙。绕住圆形障碍或钩住平台转角；锁定的墙会发出金光。",tutorial3:"笔直架桥仍可被移动。绕住石头或钩住平台转角，才能真正锁定。",failText:"墙仍未固定。请在蜜蜂碰到皮普前绕住地形或钩住平台转角。"});
  Object.assign(ja,{rulesText:"線は決して壊れません。ハチはピップを追い続け、衝突するたびに固定されていない壁を押して回転させます。障害物を囲むか、足場の角に引っ掛けた壁だけが固定され、ハチがピップに触れると失敗です。",tutorial2:"ハチは常にピップを追います。水色の壁は衝撃で滑って回転し、地形に固定された金色の壁はハチを跳ね返します。",tipsText:"2つの石を直線で結んでも壁は動きます。丸い障害物を囲むか足場の角に引っ掛けましょう。固定した壁は金色に光ります。",tutorial3:"直線の橋は動かされます。石を囲むか足場の角に引っ掛けると本当に固定できます。",failText:"壁が固定されていません。ハチがピップに届く前に地形を囲むか角に引っ掛けましょう。"});
  Object.assign(ko,{rulesText:"선은 절대 부서지지 않습니다. 벌은 계속 핍을 추격하며, 충돌할 때마다 고정되지 않은 벽을 밀고 회전시킵니다. 장애물을 감싸거나 발판 모서리에 건 벽만 고정되며, 벌이 핍에 닿으면 실패합니다.",tutorial2:"벌은 항상 핍을 추격합니다. 청록색 벽은 충돌하면 미끄러지고 회전하며, 지형에 고정된 금색 벽은 벌을 튕겨 냅니다.",tipsText:"두 돌 사이의 직선은 여전히 움직입니다. 둥근 장애물을 감싸거나 발판 모서리에 거세요. 고정된 벽은 금색으로 빛납니다.",tutorial3:"곧은 다리는 계속 움직일 수 있습니다. 돌을 감싸거나 발판 모서리에 걸어야 제대로 고정됩니다.",failText:"벽이 고정되지 않았습니다. 벌이 핍에게 닿기 전에 지형을 감싸거나 발판 모서리에 거세요."});
  Object.assign(es,{rulesText:"Las líneas nunca se rompen. Las abejas persiguen a Pip sin parar y cada choque empuja y gira los muros sueltos. Solo quedan fijos los muros que rodean un obstáculo o se enganchan a una esquina; si una abeja toca a Pip, pierdes.",tutorial2:"Las abejas siempre persiguen a Pip. Los muros cian se deslizan y giran al recibir golpes; los muros dorados fijados al terreno las hacen rebotar.",tipsText:"Una línea recta entre dos piedras sigue suelta. Rodea un obstáculo redondo o engancha una esquina de plataforma; el muro fijado brilla dorado.",tutorial3:"Un puente recto se puede mover. Rodea una piedra o engancha una esquina para fijarlo de verdad.",failText:"El muro quedó suelto. Rodea el terreno o engancha una esquina antes de que lleguen a Pip."});
  Object.assign(pt,{rulesText:"As linhas nunca quebram. As abelhas perseguem Pip sem parar, e cada impacto empurra e gira paredes soltas. Só ficam fixas as paredes que envolvem um obstáculo ou engancham no canto de uma plataforma; se uma abelha tocar Pip, você perde.",tutorial2:"As abelhas sempre perseguem Pip. Paredes ciano deslizam e giram ao serem atingidas; paredes douradas presas ao terreno rebatem as abelhas.",tipsText:"Uma linha reta entre duas pedras continua solta. Contorne um obstáculo redondo ou enganche um canto da plataforma; a parede fixa fica dourada.",tutorial3:"Uma ponte reta pode ser movida. Contorne uma pedra ou enganche um canto para fixá-la de verdade.",failText:"A parede ficou solta. Contorne o terreno ou enganche um canto antes que cheguem a Pip."});
  Object.assign(fr,{rulesText:"Les lignes ne cassent jamais. Les abeilles poursuivent Pip sans relâche et chaque choc pousse et fait pivoter les murs libres. Seuls les murs entourant un obstacle ou accrochés à un angle de plateforme sont bloqués ; si une abeille touche Pip, la tentative échoue.",tutorial2:"Les abeilles poursuivent toujours Pip. Les murs cyan glissent et pivotent sous les chocs ; les murs dorés bloqués au terrain les font rebondir.",tipsText:"Une ligne droite entre deux pierres reste libre. Entourez un obstacle rond ou accrochez un angle de plateforme ; un mur fixé devient doré.",tutorial3:"Un pont droit reste mobile. Entourez une pierre ou accrochez un angle pour le bloquer réellement.",failText:"Le mur est resté libre. Entourez le terrain ou accrochez un angle avant que les abeilles atteignent Pip."});
  Object.assign(de,{rulesText:"Linien brechen nie. Die Bienen verfolgen Pip ununterbrochen; jeder Treffer verschiebt und dreht freie Wände. Nur um ein Hindernis gelegte oder an einer Plattform-Ecke eingehakte Wände sind fest. Berührt eine Biene Pip, ist der Versuch verloren.",tutorial2:"Die Bienen verfolgen Pip ständig. Türkise Wände rutschen und drehen sich bei Treffern; am Gelände verkeilte goldene Wände lassen die Bienen abprallen.",tipsText:"Eine gerade Linie zwischen zwei Steinen bleibt beweglich. Umschlinge ein rundes Hindernis oder hake sie um eine Plattform-Ecke; feste Wände leuchten golden.",tutorial3:"Eine gerade Brücke bleibt beweglich. Umschlinge einen Stein oder hake eine Ecke ein, um sie wirklich zu fixieren.",failText:"Die Wand blieb beweglich. Umschlinge Gelände oder hake eine Plattform-Ecke ein, bevor die Bienen Pip erreichen."});
  Object.assign(it,{rulesText:"Le linee non si rompono mai. Le api inseguono sempre Pip e ogni urto spinge e ruota i muri liberi. Solo i muri avvolti attorno a un ostacolo o agganciati a un angolo della piattaforma restano fissi; se un'ape tocca Pip, perdi.",tutorial2:"Le api inseguono sempre Pip. I muri ciano scivolano e ruotano quando vengono colpiti; quelli dorati bloccati al terreno fanno rimbalzare le api.",tipsText:"Una linea retta tra due pietre resta mobile. Avvolgi un ostacolo rotondo o aggancia un angolo della piattaforma; il muro fissato diventa dorato.",tutorial3:"Un ponte diritto resta mobile. Avvolgi una pietra o aggancia un angolo per bloccarlo davvero.",failText:"Il muro è rimasto mobile. Avvolgi il terreno o aggancia un angolo prima che le api raggiungano Pip."});
  Object.assign(ru,{rulesText:"Линии никогда не ломаются. Пчёлы непрерывно преследуют Пипа, а каждый удар сдвигает и поворачивает свободную стену. Закрепляются только стены, обёрнутые вокруг препятствия или зацепленные за угол платформы; касание Пипа означает поражение.",tutorial2:"Пчёлы всегда преследуют Пипа. Голубые стены скользят и вращаются от ударов, а закреплённые на местности золотые стены отбрасывают пчёл.",tipsText:"Прямая линия между двумя камнями остаётся подвижной. Обведите круглый объект или зацепите угол платформы; закреплённая стена светится золотым.",tutorial3:"Прямой мост можно сдвинуть. Обведите камень или зацепите угол платформы, чтобы закрепить стену.",failText:"Стена осталась подвижной. Обведите объект или зацепите угол платформы до того, как пчёлы достигнут Пипа."});
  Object.assign(hi,{rulesText:"रेखाएँ कभी नहीं टूटतीं। मधुमक्खियाँ लगातार पिप का पीछा करती हैं और हर टक्कर खुली दीवार को धकेलती व घुमाती है। केवल बाधा के चारों ओर लिपटी या प्लेटफ़ॉर्म के कोने में फँसी दीवार लॉक होती है; मधुमक्खी के पिप को छूते ही प्रयास विफल होता है।",tutorial2:"मधुमक्खियाँ हमेशा पिप का पीछा करती हैं। नीली दीवारें टक्कर से खिसकती और घूमती हैं, जबकि भूभाग में फँसी सुनहरी दीवारें मधुमक्खियों को उछाल देती हैं।",tipsText:"दो पत्थरों के बीच सीधी रेखा खुली रहती है। गोल बाधा को घेरें या प्लेटफ़ॉर्म के कोने में फँसाएँ; लॉक दीवार सुनहरी चमकती है।",tutorial3:"सीधा पुल खिसक सकता है। पत्थर को घेरें या प्लेटफ़ॉर्म के कोने में फँसाकर उसे सही तरह लॉक करें।",failText:"दीवार खुली रह गई। मधुमक्खियों के पिप तक पहुँचने से पहले भूभाग को घेरें या कोने में फँसाएँ।"});
  Object.assign(ar,{rulesText:"لا تنكسر الخطوط أبداً. تواصل النحلات مطاردة بيب، وكل اصطدام يدفع الجدران الحرة ويديرها. لا يثبت إلا الجدار الملتف حول عائق أو المتشبث بزاوية منصة؛ وإذا لمست نحلة بيب تفشل المحاولة.",tutorial2:"تطارد النحلات بيب دائماً. تنزلق الجدران السماوية وتدور عند الاصطدام، بينما ترتد النحلات عن الجدران الذهبية المثبتة بالتضاريس.",tipsText:"يبقى الخط المستقيم بين حجرين حراً. لفه حول عائق دائري أو علّقه بزاوية منصة؛ يضيء الجدار المثبت باللون الذهبي.",tutorial3:"يمكن تحريك الجسر المستقيم. لف الخط حول حجر أو علّقه بزاوية منصة لتثبيته فعلاً.",failText:"بقي الجدار حراً. لفه حول التضاريس أو علّقه بزاوية قبل وصول النحلات إلى بيب."});
  // Final route-priority rule copy for Game v19.
  Object.assign(en,{rulesText:"Lines never break. Bees take any open route to Pip. They push and twist a loose wall only when no route exists, then stop pushing the instant a gap opens. Terrain wraps and platform-corner hooks hold; a bee touching Pip fails the attempt.",tutorial2:"Open route: bees detour toward Pip. No route: they push the loose wall. As soon as a gap opens, they release it and attack."});
  Object.assign(zhHant,{rulesText:"線條永遠不會斷裂。只要有通往皮普的路，蜜蜂就會直接繞行；完全沒有路時才推動並旋轉鬆牆，洞一打開就立刻停止推牆。繞住地形或勾住平台轉角可以固定；蜜蜂碰到皮普就會失敗。",tutorial2:"有路就繞向皮普，無路才推鬆牆；缺口一出現，蜜蜂會立刻放開牆並發動攻擊。"});
  Object.assign(zhHans,{rulesText:"线条永远不会断裂。只要有通往皮普的路，蜜蜂就会直接绕行；完全没有路时才推动并旋转松墙，缺口一打开就立刻停止推墙。绕住地形或钩住平台转角可以固定；蜜蜂碰到皮普就会失败。",tutorial2:"有路就绕向皮普，无路才推松墙；缺口一出现，蜜蜂会立刻放开墙并发动攻击。"});
  Object.assign(ja,{rulesText:"線は壊れません。ピップへの道があればハチは必ず迂回し、道がない時だけ自由な壁を押して回転させます。隙間が開いた瞬間に壁を離します。地形を囲むか足場の角に掛けると固定でき、ハチがピップに触れると失敗です。",tutorial2:"道があれば迂回、なければ壁を押します。隙間が開くとすぐ壁を離してピップへ向かいます。"});
  Object.assign(ko,{rulesText:"선은 부서지지 않습니다. 핍에게 가는 길이 있으면 벌은 우회하고, 길이 전혀 없을 때만 느슨한 벽을 밀고 회전시킵니다. 틈이 열리는 즉시 벽을 놓습니다. 지형을 감싸거나 발판 모서리에 걸면 고정되며, 벌이 핍에 닿으면 실패합니다.",tutorial2:"길이 있으면 우회하고, 없으면 느슨한 벽을 밉니다. 틈이 열리는 순간 벽을 놓고 핍을 공격합니다."});
  Object.assign(es,{rulesText:"Las líneas no se rompen. Si existe una ruta hasta Pip, las abejas la toman. Solo empujan y giran un muro suelto cuando no hay ruta, y lo sueltan en cuanto aparece un hueco. Rodear terreno o enganchar una esquina lo fija; si tocan a Pip, pierdes.",tutorial2:"Con ruta, las abejas rodean el muro. Sin ruta, lo empujan. En cuanto se abre un hueco, lo sueltan y atacan."});
  Object.assign(pt,{rulesText:"As linhas não quebram. Se houver uma rota até Pip, as abelhas a seguem. Só empurram e giram uma parede solta quando não há rota e param assim que surge uma abertura. Contornar o terreno ou enganchar um canto fixa a parede; tocar Pip causa derrota.",tutorial2:"Com rota, as abelhas contornam. Sem rota, empurram a parede. Quando surge uma abertura, soltam a parede e atacam."});
  Object.assign(fr,{rulesText:"Les lignes ne cassent pas. S'il existe un chemin vers Pip, les abeilles le suivent. Elles ne poussent et ne font pivoter un mur libre que sans chemin, puis le lâchent dès qu'un passage s'ouvre. Entourer le terrain ou accrocher un angle le fixe ; toucher Pip fait perdre.",tutorial2:"Avec un chemin, les abeilles contournent. Sans chemin, elles poussent le mur. Dès qu'un passage s'ouvre, elles le lâchent et attaquent."});
  Object.assign(de,{rulesText:"Linien brechen nicht. Gibt es einen Weg zu Pip, nehmen ihn die Bienen. Nur ohne Weg schieben und drehen sie eine freie Wand; sobald eine Lücke entsteht, lassen sie los. Umschlungenes Gelände oder ein Plattformhaken hält die Wand. Berührt eine Biene Pip, ist der Versuch verloren.",tutorial2:"Mit offenem Weg fliegen die Bienen herum. Ohne Weg schieben sie die Wand. Sobald eine Lücke entsteht, lassen sie los und greifen an."});
  Object.assign(it,{rulesText:"Le linee non si rompono. Se esiste un percorso verso Pip, le api lo seguono. Spingono e ruotano un muro libero solo quando non c'è un percorso e lo lasciano appena si apre un varco. Avvolgere il terreno o agganciare un angolo lo fissa; se toccano Pip, perdi.",tutorial2:"Con un percorso, le api aggirano il muro. Senza percorso, lo spingono. Appena si apre un varco, lo lasciano e attaccano."});
  Object.assign(ru,{rulesText:"Линии не ломаются. Если путь к Пипу открыт, пчёлы летят по нему. Свободную стену они толкают и поворачивают только без пути и сразу отпускают, когда появляется проход. Обводка рельефа или зацеп за угол закрепляет стену; касание Пипа означает поражение.",tutorial2:"Есть путь — пчёлы обходят стену. Пути нет — толкают её. Как только открывается проход, они отпускают стену и атакуют."});
  Object.assign(hi,{rulesText:"रेखाएँ नहीं टूटतीं। पिप तक रास्ता खुला हो तो मधुमक्खियाँ उसी से जाती हैं। रास्ता न होने पर ही वे खुली दीवार को धकेलती और घुमाती हैं, और रास्ता खुलते ही छोड़ देती हैं। भूभाग को घेरना या प्लेटफ़ॉर्म के कोने में फँसाना दीवार को रोकता है; पिप को छूते ही हार होती है।",tutorial2:"रास्ता हो तो मधुमक्खियाँ घूमकर जाती हैं। रास्ता न हो तो दीवार धकेलती हैं। रास्ता खुलते ही दीवार छोड़कर हमला करती हैं।"});
  Object.assign(ar,{rulesText:"لا تنكسر الخطوط. إذا وُجد طريق إلى بيب تسلكه النحلات. لا تدفع الجدار الحر وتديره إلا عند انعدام الطريق، وتتوقف فور ظهور ممر. يثبت الجدار عند لفه حول التضاريس أو تعليقه بزاوية منصة؛ ولمس بيب يعني الخسارة.",tutorial2:"عند وجود طريق تلتف النحلات نحو بيب. وعند انعدامه تدفع الجدار. ما إن يظهر ممر حتى تتركه وتهاجم."});
  // Game v20: one contact is a peelable pivot; a gold lock needs two anchors.
  Object.assign(en,{rulesText:"Lines never break. Bees use any open route first. With no route they push, twist, and flex a loose wall. A loop on one stone is only a pivot: the swarm peels it tight around that stone. Only one stroke hooked around two separated terrain points turns gold and holds.",tutorial2:"Open route: bees detour to Pip. No route: they approach the nearest loose wall together and move it. A new gap makes them release it instantly.",tutorial3:"One stone cannot lock a wall. Wrap or hook the same stroke around two separated terrain points; only that two-point lock turns gold.",tipsText:"A straight bridge and a one-stone circle are both loose. Use two separated wraps, opposite hooks, or a real terrain slot.",failText:"The wall had fewer than two terrain locks. The bees peeled or flexed it open and reached Pip."});
  Object.assign(zhHant,{rulesText:"線條不會斷裂。蜜蜂會優先走任何可達皮普的路；沒有路時，牠們會一起推動、扭轉並壓彎鬆動的牆。只繞一顆石頭只是支點，蜂群會沿石頭把牆剝開。必須讓同一條線勾住兩個分開的地形點，才會變成金色固定牆。",tutorial2:"有路就繞向皮普；沒路就共同靠近最近的鬆動牆並搬動。缺口一出現，蜜蜂會立刻放手進攻。",tutorial3:"一顆石頭不能鎖死牆壁。用同一條線繞住或勾住兩個分開的地形點，雙點固定才會變金色。",tipsText:"直線架在兩顆石頭之間、或只繞一顆石頭，都仍可移動。請使用兩個分開的繞點、相反勾角或真正的地形凹槽。",failText:"這面牆沒有兩個地形固定點。蜜蜂把它剝開或壓彎後抵達了皮普。"});
  Object.assign(zhHans,{rulesText:"线条不会断裂。蜜蜂会优先走任何可达皮普的路线；没有路时，它们会一起推动、扭转并压弯松动的墙。只绕一颗石头只是支点，蜂群会沿石头把墙剥开。必须让同一条线勾住两个分开的地形点，才会变成金色固定墙。",tutorial2:"有路就绕向皮普；没路就共同靠近最近的松动墙并搬动。缺口一出现，蜜蜂会立刻放手进攻。",tutorial3:"一颗石头不能锁死墙壁。用同一条线绕住或勾住两个分开的地形点，双点固定才会变金色。",tipsText:"直线架在两颗石头之间、或只绕一颗石头，都仍可移动。请使用两个分开的绕点、相反勾角或真正的地形凹槽。",failText:"这面墙没有两个地形固定点。蜜蜂把它剥开或压弯后到达了皮普。"});
  Object.assign(ja,{rulesText:"線は切れません。道があればハチは先に回り道を使い、道がなければ緩い壁を皆で押し、ひねり、曲げます。石ひとつを囲むだけでは支点にすぎず、壁は石の周りへはがされます。同じ線を離れた二つの地形に掛けた時だけ金色に固定されます。",tutorial2:"道があればピップへ迂回し、なければ最も近い緩い壁へ集まって動かします。隙間が開くとすぐ壁を離します。",tutorial3:"石ひとつでは固定できません。同じ線を離れた二つの地形に巻くか掛けると、二点固定が金色になります。",tipsText:"石二つの間の直線も、石ひとつの円も動きます。二つの巻き付き、反対向きのフック、または地形の溝を使いましょう。",failText:"地形への固定点が二つありません。ハチが壁をはがすか曲げてピップへ到達しました。"});
  Object.assign(ko,{rulesText:"선은 끊어지지 않습니다. 길이 있으면 벌은 먼저 우회하고, 길이 없으면 느슨한 벽을 함께 밀고 비틀고 휩니다. 돌 하나를 감싼 원은 지지점일 뿐이라 벌떼가 돌 둘레로 벗겨 냅니다. 같은 선을 떨어진 두 지형에 걸어야 금색으로 고정됩니다.",tutorial2:"길이 있으면 핍에게 우회합니다. 길이 없으면 가장 가까운 느슨한 벽에 함께 접근해 움직이며, 틈이 열리면 즉시 놓습니다.",tutorial3:"돌 하나로는 벽을 고정할 수 없습니다. 같은 선을 떨어진 두 지형에 감거나 걸어 두 점을 고정하세요.",tipsText:"두 돌 사이의 직선과 돌 하나를 감싼 원은 모두 움직입니다. 두 감김, 반대 방향 갈고리 또는 실제 지형 홈을 이용하세요.",failText:"지형 고정점이 두 개보다 적었습니다. 벌들이 벽을 벗기거나 휘어 핍에게 도달했습니다."});
  Object.assign(es,{rulesText:"Las líneas no se rompen. Si hay una ruta, las abejas la usan primero; si no, empujan, giran y flexionan el muro. Un círculo en una sola piedra es solo un pivote y el enjambre lo pela alrededor de ella. Solo una línea enganchada a dos puntos de terreno separados queda dorada y fija.",tutorial2:"Con ruta, rodean el muro. Sin ruta, se juntan en el muro suelto más cercano y lo mueven. Al abrirse un hueco, lo sueltan de inmediato.",tutorial3:"Una piedra no bloquea el muro. Engancha la misma línea a dos puntos de terreno separados para crear un cierre dorado.",tipsText:"Un puente recto y un círculo de una piedra siguen sueltos. Usa dos vueltas, ganchos opuestos o una ranura real del terreno.",failText:"El muro tenía menos de dos anclajes. Las abejas lo pelaron o doblaron y alcanzaron a Pip."});
  Object.assign(pt,{rulesText:"As linhas não quebram. Se houver rota, as abelhas a usam primeiro; sem rota, empurram, giram e flexionam a parede. Um círculo em uma só pedra é apenas um pivô e o enxame o descasca ao redor dela. Só uma linha presa a dois pontos separados fica dourada e fixa.",tutorial2:"Com rota, contornam a parede. Sem rota, juntam-se na parede solta mais próxima e a movem. Ao surgir uma abertura, soltam-na imediatamente.",tutorial3:"Uma pedra não fixa a parede. Prenda a mesma linha a dois pontos separados do terreno para criar a trava dourada.",tipsText:"Uma ponte reta e um círculo em uma pedra continuam soltos. Use duas voltas, ganchos opostos ou uma fenda real do terreno.",failText:"A parede tinha menos de dois apoios. As abelhas a descascaram ou dobraram e chegaram a Pip."});
  Object.assign(fr,{rulesText:"Les lignes ne cassent pas. S'il existe un chemin, les abeilles le prennent d'abord ; sinon elles poussent, tordent et plient le mur. Un cercle autour d'une seule pierre n'est qu'un pivot que l'essaim resserre. Seule une même ligne accrochée à deux points de terrain séparés devient dorée et fixe.",tutorial2:"Avec un chemin, elles contournent le mur. Sans chemin, elles rejoignent le mur libre le plus proche et le déplacent. Dès qu'un passage s'ouvre, elles le lâchent.",tutorial3:"Une pierre ne bloque pas le mur. Accrochez la même ligne à deux points de terrain séparés pour créer le verrou doré.",tipsText:"Un pont droit et un cercle autour d'une pierre restent mobiles. Utilisez deux boucles, des crochets opposés ou une vraie rainure du terrain.",failText:"Le mur avait moins de deux ancrages. Les abeilles l'ont resserré ou plié puis ont atteint Pip."});
  Object.assign(de,{rulesText:"Linien brechen nicht. Gibt es einen Weg, nehmen ihn die Bienen zuerst; sonst schieben, drehen und biegen sie die Wand. Ein Kreis um nur einen Stein ist bloß ein Drehpunkt und wird vom Schwarm eng um den Stein geschält. Erst dieselbe Linie an zwei getrennten Geländepunkten wird golden und fest.",tutorial2:"Mit offenem Weg fliegen sie herum. Ohne Weg sammeln sie sich an der nächsten losen Wand und bewegen sie. Sobald eine Lücke entsteht, lassen sie los.",tutorial3:"Ein Stein hält die Wand nicht fest. Hake dieselbe Linie an zwei getrennten Geländepunkten ein, damit sie golden wird.",tipsText:"Eine gerade Brücke und ein Kreis um einen Stein bleiben beweglich. Nutze zwei Schlingen, entgegengesetzte Haken oder eine echte Geländerinne.",failText:"Die Wand hatte weniger als zwei Geländeanker. Die Bienen schälten oder bogen sie auf und erreichten Pip."});
  Object.assign(it,{rulesText:"Le linee non si rompono. Se esiste un percorso, le api lo usano prima; altrimenti spingono, torcono e flettono il muro. Un cerchio su una sola pietra è solo un perno e lo sciame lo stringe attorno alla pietra. Solo la stessa linea agganciata a due punti separati diventa dorata e fissa.",tutorial2:"Con un percorso aggirano il muro. Senza percorso raggiungono insieme il muro libero più vicino e lo muovono. Appena si apre un varco, lo lasciano.",tutorial3:"Una pietra non blocca il muro. Aggancia la stessa linea a due punti separati del terreno per creare il fermo dorato.",tipsText:"Un ponte diritto e un cerchio su una pietra restano mobili. Usa due avvolgimenti, ganci opposti o una vera scanalatura del terreno.",failText:"Il muro aveva meno di due ancoraggi. Le api lo hanno stretto o piegato e hanno raggiunto Pip."});
  Object.assign(ru,{rulesText:"Линии не рвутся. Если путь открыт, пчёлы сразу летят по нему; иначе они толкают, крутят и гнут стену. Круг вокруг одного камня — лишь шарнир: рой стягивает стену к камню. Золотой становится только одна линия, зацепленная за две разнесённые точки рельефа.",tutorial2:"При открытом пути пчёлы обходят стену. Без пути они вместе летят к ближайшей свободной стене и двигают её. При появлении щели сразу отпускают.",tutorial3:"Один камень не фиксирует стену. Зацепите одну линию за две разнесённые точки рельефа, чтобы получить золотой замок.",tipsText:"Прямой мост и круг вокруг одного камня остаются подвижными. Нужны две петли, встречные крюки или настоящая выемка рельефа.",failText:"У стены было меньше двух опор. Пчёлы стянули или согнули её и добрались до Пипа."});
  Object.assign(hi,{rulesText:"रेखाएँ नहीं टूटतीं। रास्ता खुला हो तो मधुमक्खियाँ पहले उसी से जाती हैं; रास्ता बंद हो तो ढीली दीवार को धकेलती, मोड़ती और झुकाती हैं। एक पत्थर का घेरा केवल धुरी है और झुंड उसे पत्थर के चारों ओर कस देता है। दो अलग भू-बिंदुओं पर फँसी एक ही रेखा ही सुनहरी होकर टिकती है।",tutorial2:"रास्ता हो तो मधुमक्खियाँ पिप तक घूमकर जाती हैं। रास्ता न हो तो निकटतम ढीली दीवार पर साथ पहुँचकर उसे हिलाती हैं। छेद खुलते ही छोड़ देती हैं।",tutorial3:"एक पत्थर दीवार को स्थिर नहीं करता। एक ही रेखा को दो अलग भू-बिंदुओं पर लपेटें या फँसाएँ; तभी सुनहरा दो-बिंदु लॉक बनेगा।",tipsText:"दो पत्थरों के बीच सीधी रेखा और एक पत्थर का घेरा दोनों ढीले हैं। दो लपेट, उल्टे हुक या असली भू-खाँचा उपयोग करें।",failText:"दीवार के पास दो भू-लॉक नहीं थे। मधुमक्खियों ने उसे कसकर या मोड़कर खोल दिया और पिप तक पहुँच गईं।"});
  Object.assign(ar,{rulesText:"الخطوط لا تنكسر. إذا وُجد مسار تسلكه النحلات أولاً، وإذا انغلق الطريق تدفع الجدار الحر وتلفّه وتثنيه. الدائرة حول حجر واحد مجرد محور، فيشدها السرب حول الحجر. لا يصبح الجدار ذهبياً وثابتاً إلا إذا تعلّق الخط نفسه بنقطتين متباعدتين من التضاريس.",tutorial2:"مع وجود مسار تلتف النحلات نحو بيب. من دون مسار تتجمع عند أقرب جدار حر وتحركه. عند ظهور فجوة تتركه فوراً.",tutorial3:"حجر واحد لا يثبت الجدار. علّق الخط نفسه بنقطتين متباعدتين من التضاريس لتكوين قفل ذهبي.",tipsText:"الجسر المستقيم والدائرة حول حجر واحد كلاهما متحرك. استخدم لفتين أو خطافين متعاكسين أو شقاً حقيقياً في التضاريس.",failText:"كان للجدار أقل من نقطتي تثبيت. شدته النحلات أو ثنته حتى وصلت إلى بيب."});
  // Game v21: a spanning loose wall escapes along its open axis before flexing.
  Object.assign(en,{tutorial2:"Open route: bees detour to Pip. No route: they move a spanning wall sideways toward the nearest open edge. The instant a gap opens, they release it and attack."});
  Object.assign(zhHant,{tutorial2:"有路就繞向皮普；沒路時，橫跨場地的鬆牆會被蜂群往最近的開放側邊搬移。缺口一出現，蜜蜂立刻放手進攻。"});
  Object.assign(zhHans,{tutorial2:"有路就绕向皮普；没路时，横跨场地的松墙会被蜂群往最近的开放侧边搬移。缺口一出现，蜜蜂立刻放手进攻。"});
  Object.assign(ja,{tutorial2:"道があればピップへ迂回します。道がなければ、場を横切る緩い壁を最も近い開いた端へ横移動させます。隙間が開くとすぐ壁を離して攻撃します。"});
  Object.assign(ko,{tutorial2:"길이 있으면 핍에게 우회합니다. 길이 없으면 벌떼가 가로막은 느슨한 벽을 가장 가까운 열린 가장자리 쪽으로 옮깁니다. 틈이 열리는 즉시 벽을 놓고 공격합니다."});
  Object.assign(es,{tutorial2:"Con ruta, rodean el muro hacia Pip. Sin ruta, desplazan de lado un muro que cruza el campo hacia el borde abierto más cercano. Al abrirse un hueco, lo sueltan y atacan."});
  Object.assign(pt,{tutorial2:"Com rota, contornam até Pip. Sem rota, movem de lado uma parede que cruza o campo até a borda aberta mais próxima. Ao surgir uma abertura, soltam e atacam."});
  Object.assign(fr,{tutorial2:"Avec un chemin, elles contournent vers Pip. Sans chemin, elles déplacent latéralement un mur traversant le terrain vers le bord libre le plus proche. Dès qu'un passage s'ouvre, elles le lâchent et attaquent."});
  Object.assign(de,{tutorial2:"Mit offenem Weg fliegen sie zu Pip. Ohne Weg schieben sie eine quer verlaufende lose Wand seitlich zum nächsten offenen Rand. Sobald eine Lücke entsteht, lassen sie los und greifen an."});
  Object.assign(it,{tutorial2:"Con un percorso aggirano il muro verso Pip. Senza percorso spostano di lato un muro che attraversa il campo verso il bordo libero più vicino. Appena si apre un varco, lo lasciano e attaccano."});
  Object.assign(ru,{tutorial2:"Если путь открыт, пчёлы обходят стену к Пипу. Без пути они сдвигают поперечную свободную стену к ближайшему открытому краю. Как только появляется проход, отпускают её и атакуют."});
  Object.assign(hi,{tutorial2:"रास्ता हो तो मधुमक्खियाँ घूमकर पिप तक जाती हैं। रास्ता न हो तो मैदान रोकने वाली ढीली दीवार को निकटतम खुले किनारे की ओर सरकाती हैं। छेद खुलते ही छोड़कर हमला करती हैं।"});
  Object.assign(ar,{tutorial2:"عند وجود مسار تلتف النحلات نحو بيب. وعند انعدامه تحرك الجدار الحر الممتد جانبياً نحو أقرب حافة مفتوحة. ما إن يظهر ممر حتى تتركه وتهاجم."});
  Object.assign(zhHant,{guideExtra:"開始前先觀察草原，再決定第一筆線要放在哪裡。皮普最安全的情況，是防線形成蜜蜂不能直接繞過的短路線；太長的牆會消耗更多花蜜，也會留下更大的受力面。請在小狗周圍留一點空間，這樣補線時才不會困住下一筆筆畫。防線閃紅時，先修補那一小段弱點，不要立刻把整個形狀重畫。第一條有效的線會開始波次，所以草原安靜時可以先看清楚蜂巢、石頭與可能的入口。蜜蜂開始移動後，要觀察牠們的來向，而不只是盯著手上的線；看似安全的牆，可能仍在皮普身後留下開口。兩個分開的地形錨點比單一圓圈可靠。只繞一顆石頭時，牆仍可能以它為支點旋轉或被蜂群剝開；同一筆線繞過兩個不同的石頭、平台角落或有效地形點，才會固定並發出金色光芒。若蜜蜂正在推動鬆動的牆，不要慌張地反覆重畫。先看牠們想打開哪個缺口，再用短鉤線封住那條路。花蜜有限，精準的小修補通常比第二個大圓圈更容易拿到高星。進入後面的章節前，重新閱讀章節提示：新增蜂巢、分岔來向、風勢、脆弱缺口與混合波次，都會改變最短安全防線的形狀。過關後下一條路線會自動解鎖，最佳星級只保存在這個瀏覽器。失敗不會上傳帳號資料，回到關卡列表、研究紅色缺口，再換一種形狀嘗試即可。"});
  Object.assign(zhHans,{guideExtra:"开始前先观察草原，再决定第一笔线要放在哪里。皮普最安全的情况，是防线形成蜜蜂不能直接绕过的短路线；太长的墙会消耗更多花蜜，也会留下更大的受力面。请在小狗周围留一点空间，这样补线时才不会困住下一笔笔画。防线闪红时，先修补那一小段弱点，不要立刻把整个形状重画。第一条有效的线会开始波次，所以草原安静时可以先看清蜂巢、石头与可能的入口。蜜蜂开始移动后，要观察它们的来向，而不只是盯着手上的线；看似安全的墙，可能仍在皮普身后留下开口。两个分开的地形锚点比单一圆圈可靠。只绕一颗石头时，墙仍可能以它为支点旋转或被蜂群剥开；同一笔线绕过两个不同的石头、平台角落或有效地形点，才会固定并发出金色光芒。如果蜜蜂正在推动松动的墙，不要慌张地反复重画。先看它们想打开哪个缺口，再用短钩线封住那条路。花蜜有限，精准的小修补通常比第二个大圆圈更容易拿到高星。进入后面的章节前，重新阅读章节提示：新增蜂巢、分岔来向、风势、脆弱缺口与混合波次，都会改变最短安全防线的形状。过关后下一条路线会自动解锁，最佳星级只保存在这个浏览器。失败不会上传账号资料，回到关卡列表、研究红色缺口，再换一种形状尝试即可。"});
  Object.assign(ja,{guideExtra:"描き始める前に草原を観察し、最初の線を置く場所を決めましょう。ピップが安全なのは、ハチが簡単には回り込めない短い道をバリアが作ったときです。長い壁は蜜を多く使い、ハチに押される面も広くなります。子犬の周りには少し余白を残すと、修理の線が次の一筆を邪魔しません。バリアが赤く点滅したら、形全体を描き直す前に弱い部分を直します。最初の有効な線でウェーブが始まるので、草原が静かなうちに巣や石、入口を見ておけます。ハチが動き始めたら、描いている線だけでなく進んでくる方向も確認しましょう。安全に見える壁でも、ピップの後ろに開口部が残ることがあります。一つの石を囲むだけでは壁は支点として回ったり、ハチの群れに剥がされたりします。離れた二つの石や地形の角に同じ線を掛けると、壁は固定されて金色に光ります。壁が押されても慌てて何度も描き直さず、ハチが開けようとしている隙間を見て短いフックで閉じましょう。蜜には限りがあるため、大きな円をもう一つ描くより小さな修理のほうが星を取りやすいです。後半の章では巣、分岐、風、壊れやすい隙間、混合ウェーブが増えます。章のヒントを読み直し、その道に合う短い形を試してください。クリアすると次のルートが自動で開き、最高記録はこのブラウザーだけに保存されます。"});
  Object.assign(ko,{guideExtra:"그리기 전에 초원을 살펴보고 첫 선을 놓을 위치를 정하세요. 핍이 안전한 때는 방어선이 벌이 쉽게 돌아갈 수 없는 짧은 길을 만들었을 때입니다. 긴 벽은 꽃꿀을 더 많이 쓰고 벌이 밀어낼 면도 넓어집니다. 강아지 주변에 약간의 공간을 남겨야 수리 선이 다음 선을 방해하지 않습니다. 방어선이 빨갛게 깜박이면 전체 모양을 다시 그리기보다 약한 부분부터 고치세요. 첫 번째 유효한 선이 파도를 시작하므로 초원이 조용할 때 벌집과 돌, 가능한 입구를 먼저 확인할 수 있습니다. 벌이 움직이기 시작하면 손으로 그리고 있는 선뿐 아니라 벌이 오는 방향도 보세요. 안전해 보이는 벽도 핍 뒤에 열린 모서리를 남길 수 있습니다. 돌 하나만 감싸면 벽은 그 돌을 중심으로 회전하거나 벌 떼에 벗겨질 수 있습니다. 서로 떨어진 두 돌이나 지형 모서리에 같은 선을 걸면 벽이 고정되고 금빛으로 빛납니다. 느슨한 벽이 밀릴 때 서둘러 계속 다시 그리지 말고, 벌이 열려고 하는 틈을 확인한 뒤 짧은 갈고리로 그 길을 닫으세요. 꽃꿀은 한정되어 있으므로 큰 원을 하나 더 그리는 것보다 작은 수리가 별을 얻는 데 유리합니다. 뒤쪽 챕터에는 벌집, 갈라진 접근로, 바람, 약한 틈, 혼합 파도가 추가됩니다. 챕터 힌트를 다시 읽고 그 길에 맞는 짧은 모양을 시험하세요. 클리어하면 다음 경로가 자동으로 열리고 최고 기록은 이 브라우저에만 저장됩니다."});
  Object.assign(es,{guideExtra:"Empieza observando el prado antes de dibujar. Pip está más seguro cuando la barrera crea un camino corto que las abejas no pueden rodear, pero un muro largo cuesta más néctar y ofrece más superficie para empujar. Deja espacio alrededor del cachorro para que una reparación no encierre tu siguiente línea. Si una barrera parpadea en rojo, repara esa parte débil antes de rehacerla. La primera línea válida inicia la oleada, así que puedes planear mientras el prado está tranquilo. Cuando las abejas se muevan, observa su ruta y no solo la línea: una defensa segura puede dejar una esquina abierta detrás de Pip. Dos anclajes de terreno separados son más fuertes que un solo lazo. Una piedra permite que el muro gire o se deslice; rodear dos puntos distintos fija la línea y la vuelve dorada. Si las abejas empujan un muro suelto, espera a ver qué hueco intentan abrir y añade un gancho corto. El néctar es limitado y las reparaciones eficientes dan más estrellas que otro círculo grande. Antes de cada capítulo, lee su pista: nuevas colmenas, rutas divididas, ráfagas, huecos frágiles y oleadas mixtas cambian la línea más corta. Tras superar una fase, la siguiente ruta se desbloquea y tus mejores estrellas quedan guardadas en este navegador. Fallar no borra datos; vuelve a las fases, estudia la abertura roja y prueba otra forma. También puedes repetir rutas para comparar estrellas y aprender qué lado del prado ofrece menos opciones a las abejas."});
  Object.assign(pt,{guideExtra:"Comece observando o prado antes de desenhar. Pip fica mais seguro quando a barreira cria uma rota curta que as abelhas não conseguem contornar, mas uma parede longa gasta mais néctar e oferece mais superfície para empurrar. Deixe espaço ao redor do filhote para que um reparo não prenda sua próxima linha. Se a barreira piscar em vermelho, repare primeiro o trecho fraco. A primeira linha válida inicia a onda, então você pode planejar enquanto o prado está calmo. Quando as abelhas se moverem, observe a rota delas e não apenas a linha: uma defesa aparentemente segura pode deixar um canto aberto atrás de Pip. Dois apoios separados no terreno são mais fortes que um único laço. Uma pedra permite que a parede gire ou descasque; prender a mesma linha em dois pontos distintos faz ela ficar dourada e firme. Se as abelhas empurrarem uma parede solta, espere o vão que tentam abrir e faça um gancho curto. O néctar é limitado, e reparos eficientes rendem mais estrelas que outro círculo grande. Antes de cada capítulo, releia a dica: novas colmeias, rotas divididas, rajadas, brechas frágeis e ondas mistas mudam o desenho mais curto. Depois de vencer, a próxima rota é desbloqueada e suas melhores estrelas ficam neste navegador. Falhar não apaga dados; volte às fases, observe a abertura vermelha e tente outra forma. Você também pode repetir rotas para comparar estrelas e aprender qual lado do prado oferece menos escolhas às abelhas."});
  Object.assign(fr,{guideExtra:"Commencez par observer la prairie avant de dessiner. Pip est plus sûr lorsque la barrière crée un chemin court que les abeilles ne peuvent pas contourner, mais un long mur coûte plus de nectar et offre davantage de prise à l'essaim. Laissez un peu d'espace autour du chiot afin qu'une réparation ne piège pas votre prochain tracé. Si une barrière clignote en rouge, réparez d'abord sa partie faible. La première ligne valide lance la vague : vous pouvez donc préparer votre idée dans le calme. Quand les abeilles bougent, observez leur chemin plutôt que la ligne seule : un mur apparemment sûr peut laisser un angle ouvert derrière Pip. Deux ancrages séparés dans le terrain sont plus solides qu'une seule boucle. Une pierre laisse pivoter ou peler le mur ; accrocher la même ligne à deux points distincts la rend dorée et fixe. Si les abeilles poussent un mur libre, attendez le passage qu'elles cherchent à ouvrir puis ajoutez un petit crochet. Le nectar est limité et les réparations efficaces rapportent plus d'étoiles qu'un grand cercle supplémentaire. Avant chaque chapitre, relisez son indice : ruches, approches divisées, rafales, brèches fragiles et vagues mixtes changent le tracé le plus court. Après une réussite, le parcours suivant se débloque et vos meilleures étoiles restent dans ce navigateur. Un échec n'efface aucune donnée : revenez aux niveaux, étudiez l'ouverture rouge et essayez une autre forme. Vous pouvez aussi rejouer un parcours pour comparer les étoiles et apprendre quel côté de la prairie laisse le moins de choix aux abeilles."});
  Object.assign(de,{guideExtra:"Beobachte die Wiese zuerst, bevor du zeichnest. Pip ist am sichersten, wenn die Barriere einen kurzen Weg erzeugt, den die Bienen nicht einfach umgehen können. Eine lange Wand kostet jedoch mehr Nektar und bietet dem Schwarm mehr Angriffsfläche. Lass etwas Platz um den Welpen, damit eine Reparatur deine nächste Linie nicht einschließt. Blinkt eine Barriere rot, repariere zuerst die schwache Stelle. Die erste gültige Linie startet die Welle, deshalb kannst du in der Ruhe planen. Sobald die Bienen fliegen, beobachte ihren Weg und nicht nur die Linie: Hinter Pip kann eine scheinbar sichere Wand eine offene Ecke lassen. Zwei getrennte Geländean­ker sind stärker als eine einzelne Schleife. An einem Stein kann sich die Wand drehen oder ablösen; dieselbe Linie an zwei verschiedenen Punkten wird golden und fest. Wenn Bienen eine lose Wand schieben, warte auf die Lücke, die sie öffnen wollen, und setze einen kurzen Haken. Nektar ist begrenzt, und sparsame Reparaturen bringen mehr Sterne als ein weiterer großer Kreis. Lies vor jedem Kapitel den Hinweis erneut: neue Bienenstöcke, geteilte Wege, Böen, fragile Lücken und gemischte Wellen verändern die kürzeste sichere Linie. Nach einem Sieg wird die nächste Route freigeschaltet; deine besten Sterne bleiben in diesem Browser. Ein Fehlschlag löscht keine Daten: Kehre zu den Stufen zurück, studiere die rote Öffnung und probiere eine andere Form. Wiederhole frühere Routen, um Sterne zu vergleichen und die Seite mit den wenigsten Möglichkeiten für die Bienen zu lernen."});
  Object.assign(it,{guideExtra:"Prima di disegnare, osserva il prato. Pip è più al sicuro quando la barriera crea un percorso breve che le api non possono aggirare facilmente, ma un muro lungo consuma più nettare e offre allo sciame più superficie da spingere. Lascia spazio attorno al cucciolo, così una riparazione non intrappola la linea successiva. Se una barriera lampeggia in rosso, ripara prima quel punto debole. La prima linea valida avvia l'ondata, quindi puoi pianificare mentre il prato è tranquillo. Quando le api si muovono, guarda il loro percorso e non solo la linea: una difesa sicura può lasciare un angolo aperto dietro Pip. Due ancoraggi separati nel terreno sono più forti di un solo anello. Una pietra lascia ruotare o sfilare il muro; collegare la stessa linea a due punti diversi la rende dorata e ferma. Se le api spingono un muro libero, aspetta il varco che cercano e aggiungi un piccolo gancio. Il nettare è limitato e le riparazioni efficienti danno più stelle di un altro cerchio grande. Prima di ogni capitolo rileggi l'indizio: nuovi alveari, percorsi divisi, raffiche, varchi fragili e ondate miste cambiano la linea più breve. Dopo una vittoria si sblocca il percorso successivo e le stelle migliori restano in questo browser. Una sconfitta non cancella dati: torna ai livelli, studia l'apertura rossa e prova una forma diversa. Puoi anche rigiocare i percorsi per confrontare le stelle e scoprire quale lato del prato lascia meno scelte alle api."});
  Object.assign(ru,{guideExtra:"Сначала изучите луг, а уже потом рисуйте. Пипу безопаснее, когда стена создаёт короткий путь, который пчёлы не могут просто обойти, но длинная стена тратит больше нектара и даёт рою большую поверхность для толчков. Оставьте вокруг щенка немного места, чтобы ремонт не запер следующую линию. Если стена мигает красным, сначала укрепите слабый участок. Первая правильная линия запускает волну, поэтому план можно подготовить в тишине. Когда пчёлы полетят, следите за их маршрутом, а не только за линией: за Пипом может остаться открытый угол. Два раздельных контакта с рельефом надёжнее одной петли. О камень стена может поворачиваться или сжиматься; одна и та же линия, зацепленная за две разные точки, станет золотой и неподвижной. Если пчёлы толкают свободную стену, дождитесь прохода, который они пытаются открыть, и добавьте короткий крюк. Нектар ограничен, поэтому аккуратный ремонт приносит больше звёзд, чем ещё один большой круг. Перед каждой главой перечитайте подсказку: новые ульи, разделённые подходы, порывы, хрупкие проходы и смешанные волны меняют самый короткий безопасный рисунок. После победы открывается следующий маршрут, а лучшие звёзды остаются в этом браузере. Поражение не стирает данные: вернитесь к этапам, изучите красный разрыв и попробуйте другую форму. Повторяйте маршруты, чтобы сравнивать звёзды и находить сторону луга с меньшим числом вариантов для пчёл."});
  Object.assign(hi,{guideExtra:"रेखा बनाने से पहले मैदान को ध्यान से देखें। पिप तब अधिक सुरक्षित रहता है जब बाधा ऐसा छोटा रास्ता बनाए जिसे मधुमक्खियाँ आसानी से घेरकर पार न कर सकें, लेकिन लंबी दीवार अधिक नेक्टर खर्च करती है और झुंड को धक्का देने के लिए अधिक सतह देती है। पिल्ले के चारों ओर थोड़ी जगह छोड़ें ताकि मरम्मत आपकी अगली रेखा को न फँसाए। बाधा लाल चमके तो पहले उसी कमजोर हिस्से को ठीक करें। पहली सही रेखा लहर शुरू करती है, इसलिए शांत मैदान में योजना बना लें। मधुमक्खियाँ चलने लगें तो केवल रेखा नहीं, उनका रास्ता देखें: पिप के पीछे कोई खुला कोना बच सकता है। भूभाग के दो अलग संपर्क एक ही घेराव से मजबूत होते हैं। एक पत्थर पर दीवार घूम या खिसक सकती है; उसी रेखा को दो अलग बिंदुओं से जोड़ने पर वह सुनहरी और स्थिर होती है। ढीली दीवार को मधुमक्खियाँ धकेलें तो उस खुली जगह को देखें जिसे वे बनाना चाहती हैं और छोटा हुक जोड़ें। नेक्टर सीमित है, इसलिए कुशल मरम्मत बड़े दूसरे घेरे से अधिक सितारे दे सकती है। हर अध्याय से पहले संकेत पढ़ें: नए छत्ते, बँटे रास्ते, झोंके, नाज़ुक खाली जगहें और मिली-जुली लहरें सबसे छोटी सुरक्षित रेखा बदल देती हैं। जीत के बाद अगला रास्ता खुलता है और आपके अच्छे सितारे इसी ब्राउज़र में रहते हैं। हारने से डेटा नहीं मिटता; चरणों पर लौटें, लाल खुली जगह देखें और अलग आकार आज़माएँ। पुराने रास्ते दोहराकर सितारों की तुलना करें और जानें कि मैदान का कौन सा किनारा मधुमक्खियों को कम विकल्प देता है।"});
  Object.assign(ar,{guideExtra:"ابدأ بمراقبة المرج قبل الرسم. يكون بيب أكثر أماناً عندما يصنع الحاجز طريقاً قصيراً لا يستطيع النحل الالتفاف حوله بسهولة، لكن الجدار الطويل يستهلك رحيقاً أكثر ويمنح السرب مساحة أكبر لدفعه. اترك مساحة حول الجرو حتى لا يحاصر الإصلاح خطك التالي. إذا ومض الحاجز بالأحمر فأصلح الجزء الضعيف أولاً. يبدأ الخط الصحيح الأول الموجة، لذلك يمكنك التخطيط بينما المرج هادئ. عندما يتحرك النحل راقب طريقه لا الخط وحده؛ فقد تبقى زاوية مفتوحة خلف بيب. نقطتا تماس منفصلتان مع التضاريس أقوى من حلقة واحدة. يمكن للجدار أن يدور أو ينزلق حول حجر، أما ربط الخط نفسه بنقطتين مختلفتين فيجعله ذهبياً وثابتاً. إذا دفع النحل جداراً غير مثبت فراقب الفتحة التي يحاول فتحها وأضف خطافاً قصيراً. الرحيق محدود، والإصلاح الدقيق يمنح نجوماً أكثر من دائرة كبيرة أخرى. اقرأ تلميح كل فصل قبل البدء؛ فخلايا النحل الجديدة والمسارات المنقسمة والهبّات والفجوات الهشة والموجات المختلطة تغيّر أقصر خط آمن. بعد النجاح يفتح المسار التالي وتبقى أفضل نجومك في هذا المتصفح. الفشل لا يمسح البيانات؛ عد إلى المراحل وادرس الفتحة الحمراء وجرب شكلاً مختلفاً. أعد لعب المسارات لمقارنة النجوم ومعرفة أي جانب من المرج يترك للنحل خيارات أقل."});
